#!/usr/bin/env node
/**
 * build-chatgpt-plugin — assemble the ZIP that OpenAI's plugin portal imports
 * (platform.openai.com/plugins → upload; see docs/chatgpt-plugin/README.md).
 *
 *   node scripts/build-chatgpt-plugin.mjs
 *   → docs/chatgpt-plugin/dist/basedagents-chatgpt-plugin.zip  (gitignored)
 *
 * Layout (Agent Plugins format, everything at the ZIP root):
 *   plugin.json   ← docs/chatgpt-plugin/package/plugin.json (generated by sync-positioning)
 *   mcp.json      ← docs/chatgpt-plugin/package/mcp.json    (generated by sync-positioning)
 *   assets/logo.png, assets/composerIcon.png ← packages/web/public/icon-512.png
 *
 * Fails before zipping when the package is stale (sync drift), a file the
 * manifest references is missing, or an icon breaks the portal's rules
 * (square, ≥48×48, ≤4096 per side, ≤5 MiB).
 */
import { readFileSync, mkdirSync, rmSync, copyFileSync, statSync, existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const PKG = join(ROOT, 'docs/chatgpt-plugin/package');
const DIST = join(ROOT, 'docs/chatgpt-plugin/dist');
const STAGE = join(DIST, 'stage');
const ZIP = join(DIST, 'basedagents-chatgpt-plugin.zip');
const ICON = join(ROOT, 'packages/web/public/icon-512.png');

function fail(msg) {
  console.error(`build-chatgpt-plugin: ${msg}`);
  process.exit(1);
}

// The manifest's listing text is generated; a stale copy would upload old copy.
const sync = spawnSync('npx', ['tsx', 'scripts/sync-positioning.ts', '--check'], { cwd: ROOT, encoding: 'utf8' });
if (sync.status !== 0) fail(`package is stale: run npx tsx scripts/sync-positioning.ts first\n${sync.stderr || sync.stdout}`);

/** PNG width/height from the IHDR chunk (bytes 16–23). */
function pngSize(file) {
  const b = readFileSync(file);
  if (b.length < 24 || b.toString('ascii', 1, 4) !== 'PNG') fail(`${file} is not a PNG`);
  return { w: b.readUInt32BE(16), h: b.readUInt32BE(20) };
}
const { w, h } = pngSize(ICON);
if (w !== h || w < 48 || w > 4096) fail(`icon must be square, 48–4096 px per side; got ${w}×${h}`);
if (statSync(ICON).size > 5 * 1024 * 1024) fail('icon exceeds 5 MiB');

rmSync(STAGE, { recursive: true, force: true });
mkdirSync(join(STAGE, 'assets'), { recursive: true });
copyFileSync(join(PKG, 'plugin.json'), join(STAGE, 'plugin.json'));
copyFileSync(join(PKG, 'mcp.json'), join(STAGE, 'mcp.json'));
copyFileSync(ICON, join(STAGE, 'assets/logo.png'));
copyFileSync(ICON, join(STAGE, 'assets/composerIcon.png'));

// Every ./path the manifest references must ship in the ZIP.
const iface = JSON.parse(readFileSync(join(STAGE, 'plugin.json'), 'utf8')).extensions['com.openai'].interface;
for (const key of ['logo', 'logoDark', 'composerIcon', 'composerIconDark']) {
  const ref = iface[key];
  if (ref && !existsSync(join(STAGE, ref))) fail(`plugin.json ${key} → ${ref} is not in the package`);
}

rmSync(ZIP, { force: true });
// -X: no extra file attributes, so the archive is the same across machines.
const zip = spawnSync('zip', ['-r', '-X', ZIP, 'plugin.json', 'mcp.json', 'assets'], { cwd: STAGE, encoding: 'utf8' });
if (zip.status !== 0) fail(`zip failed (is the zip CLI installed?)\n${zip.stderr || zip.stdout}`);
rmSync(STAGE, { recursive: true, force: true });
console.log(`wrote ${ZIP.replace(ROOT + '/', '')} (${statSync(ZIP).size} bytes): plugin.json, mcp.json, assets/logo.png, assets/composerIcon.png (${w}×${h})`);
